import React, { useEffect, useState } from "react";
import Header from "./Header";
import Footer from "./Footer";
import "./resultList.css";
import { useNavigate } from "react-router-dom";

const ResultListPage = () => {
  const [testData, setTestData] = useState({
    incomplete_tests: [],
    tests_with_pending_results: [],
    tests_with_results: [],
  });
  const [message, setMessage] = useState(null);
  const [activeTab, setActiveTab] = useState("incomplete"); // Default to "incomplete tests"
  const navigate = useNavigate();

  useEffect(() => {
    const fetchTestData = async () => {
      try {
        const rollno = localStorage.getItem("userEmail");
        if (!rollno) {
          setMessage("Roll number not found. Please log in.");
          return;
        }

        const response = await fetch("http://localhost:5000/resultlist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ rollno }),
        });

        if (response.ok) {
          const data = await response.json();
          setTestData({
            incomplete_tests: data.incomplete_tests ?? [],
            tests_with_pending_results: data.tests_with_pending_results ?? [],
            tests_with_results: data.tests_with_results ?? [],
          });
        } else {
          const error = await response.json();
          setMessage(error.error || "Failed to fetch test data.");
        }
      } catch (err) {
        setMessage("Error: Something went wrong.");
      }
    };

    fetchTestData();
  }, []);

  const handleAction = (testId, action) => {
    if (action === "view_result") {
      localStorage.setItem("test_id", testId);
      navigate("/completion-page");
    }
  };

  const renderTests = () => {
    let tests = [];
    let actionLabel = "";
    let actionType = "";

    if (activeTab === "incomplete") {
      tests = testData.incomplete_tests;
      actionLabel = "Resume";
      actionType = "resume";
    } else if (activeTab === "pending") {
      tests = testData.tests_with_pending_results;
      actionLabel = "Check Result";
      actionType = "check_result";
    } else {
      tests = testData.tests_with_results;
      actionLabel = "View Result";
      actionType = "view_result";
    }

    return tests.length > 0 ? (
      tests.map((test) => (
        <div key={test.test_id} className="test-item">
          <span>Test ID: {test.test_id}</span>
          <span>Created At: {test.created_at}</span>
          <button onClick={() => handleAction(test.test_id, actionType)} className="action-button">
            {actionLabel}
          </button>
        </div>
      ))
    ) : (
      <p>No {activeTab} tests available.</p>
    );
  };

  return (
    <div className="app">
      <Header />
      <div className="result-container">
        <div className="content-section">
          <h2>Test Status</h2>
          {message && <p className="feedback-message">{message}</p>}

          <div className="tab-buttons">
            <button className={`tab-button ${activeTab === "incomplete" ? "active" : ""}`} onClick={() => setActiveTab("incomplete")}>
              Incomplete Tests
            </button>
            <button className={`tab-button ${activeTab === "pending" ? "active" : ""}`} onClick={() => setActiveTab("pending")}>
              Pending Tests
            </button>
            <button className={`tab-button ${activeTab === "results" ? "active" : ""}`} onClick={() => setActiveTab("results")}>
              Results
            </button>
          </div>

          <div className="test-list">{renderTests()}</div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ResultListPage;
